def transform(g):
    g=[row[:] for row in g]; n=len(g)
    def mirror(i): return n+1-i if 2<=i<=n-1 else i  # r<->31-r for rows 2..29 (n=30)
    changed=True
    while changed:
        changed=False
        for r in range(n):
            for c in range(n):
                if g[r][c]==6:
                    for (a,b) in [(c,r),(mirror(r),c),(r,mirror(c))]:
                        if 0<=a<n and 0<=b<n and g[a][b]!=6:
                            g[r][c]=g[a][b]; changed=True; break
    return g
